import { type ReactNode } from 'react';

type TagVariant = 'ghost' | 'filled' | 'outlined';
type TagIntent = 'success' | 'warning' | 'danger' | 'info' | 'neutral' | 'brand' | 'ai' | 'disabled';
type TagSize = 'xs' | 's' | 'm';

export type TagProps = {
  variant?: TagVariant;
  intent?: TagIntent;
  size?: TagSize;
  dot?: boolean;
  icon?: ReactNode;
  avatar?: string;
  children: string;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export function Tag({
  variant = 'filled',
  intent = 'neutral',
  size = 's',
  dot = false,
  icon,
  avatar,
  children,
  className,
}: TagProps) {
  const classes = cn(
    'tag',
    `tag--${variant}`,
    `tag--${intent}`,
    `tag--${size}`,
    className,
  );

  return (
    <span className={classes}>
      {dot && <span className="tag__dot" />}
      {avatar && (
        <span className="tag__avatar">
          <img src={avatar} alt="" />
        </span>
      )}
      {icon && <span className="tag__icon">{icon}</span>}
      <span className="tag__label">{children}</span>
    </span>
  );
}

/* -------------------------------------------------------------------------
   Tag

   Status pill for categories, labels, and section headings.
   Pill shape (border-radius: 1000px). Non-interactive.

   Variants: ghost (no bg), filled (bg), outlined (border)
   Intents:  success, warning, danger, info, neutral, brand, ai, disabled
   Sizes:    xs (16px), s (20px), m (24px)
   Features: hasDots, hasIcon, hasAvatar
   ------------------------------------------------------------------------- */

.tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-1);
  max-width: 12.5rem;
  border-radius: var(--radius-full);
  border: var(--stroke-thin) solid transparent;
  font-family: var(--font-family-sans);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---- Sizes ---- */

.tag--xs { height: 1rem; padding: 0 var(--spacing-2); font-size: var(--font-size-xs); }
.tag--s  { height: 1.25rem; padding: 0 var(--spacing-2); font-size: var(--font-size-xs); }
.tag--m  { height: 1.5rem; padding: 0 var(--spacing-2); font-size: var(--font-size-sm); }

/* ---- l: eyebrow de hero ----
   El unico tamano pensado para FRASE, no para etiqueta de estado: por eso
   levanta el max-width de 12.5rem y el nowrap del bloque base. Sin esto una
   frase como "Inteligencia de Conversion para WhatsApp" se corta con ellipsis. */

.tag--l {
  height: auto;
  max-width: none;
  padding: var(--spacing-2) var(--spacing-4);
  font-size: var(--font-size-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: var(--font-weight-semibold);
  white-space: normal;
  overflow: visible;
}

/* ---- Mono (patron ATOM: etiqueta tecnica) ---- */
/* Tipografia mono en caja recta. Combina con --inverse o cualquier intent. */

.tag--mono {
  font-family: var(--font-family-mono);
  font-weight: var(--font-weight-regular);
  font-size: var(--font-size-xs);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
}

/* ---- Gradient (borde degradado de marca) ----
   Highlight tipografico del sistema: el mismo --gradient-highlight del
   .text-gradient, aqui como CONTORNO. El borde degradado se hace con dos capas
   de background y distintos clip boxes — un border-image no permite radio, y
   este pill es radius-full. Por eso el border va transparent: es la ventana por
   la que se ve la capa de gradiente. */

.tag--gradient {
  border-color: transparent;
  background-image:
    linear-gradient(var(--background), var(--background)),
    var(--gradient-highlight);
  background-origin: border-box;
  background-clip: padding-box, border-box;
  color: var(--foreground);
}

/* ---- Inverse (relleno con los semantics del contexto: flipa en dark) ---- */

.tag--inverse {
  color: var(--background);
  background-color: var(--foreground);
}

/* ---- Ghost (text only, no bg) ---- */

.tag--ghost.tag--success   { color: var(--success-text); }
.tag--ghost.tag--warning   { color: var(--warning-text); }
.tag--ghost.tag--danger    { color: var(--destructive-text); }
.tag--ghost.tag--info      { color: var(--info-text); }
.tag--ghost.tag--neutral   { color: var(--foreground); }
.tag--ghost.tag--brand     { color: var(--brand-text); }
.tag--ghost.tag--ai        { color: var(--ai-text); }
.tag--ghost.tag--disabled  { color: var(--muted-foreground); }

/* ---- Filled (bg + text) ---- */

.tag--filled.tag--success   {
  background-color: color-mix(in srgb, var(--success) 18%, var(--background));
  color: var(--success-text);
}
.tag--filled.tag--warning   {
  background-color: color-mix(in srgb, var(--warning) 18%, var(--background));
  color: var(--warning-text);
}
.tag--filled.tag--danger    {
  background-color: color-mix(in srgb, var(--destructive) 16%, var(--background));
  color: var(--destructive-text);
}
.tag--filled.tag--info      {
  background-color: color-mix(in srgb, var(--info) 18%, var(--background));
  color: var(--info-text);
}
.tag--filled.tag--neutral   { background-color: var(--muted); color: var(--foreground); }
.tag--filled.tag--brand     {
  background-color: color-mix(in srgb, var(--brand) 18%, var(--background));
  color: var(--brand-text);
}
/* El stop de arranque era --success: mientras ai no tuvo superficie propia, el
   intent se pintaba de verde y no se distinguia del de exito. Ahora arranca en
   su propio violeta. */
.tag--filled.tag--ai        {
  background: linear-gradient(
    136deg,
    color-mix(in srgb, var(--ai) 20%, var(--background)),
    color-mix(in srgb, var(--ai-text) 12%, var(--background))
  );
  color: var(--ai-text);
}
.tag--filled.tag--disabled  { background-color: var(--muted); color: var(--muted-foreground); }

/* ---- Outlined (border + text) ---- */

.tag--outlined.tag--success   { border-color: var(--success-text); color: var(--success-text); }
.tag--outlined.tag--warning   { border-color: var(--warning-text); color: var(--warning-text); }
.tag--outlined.tag--danger    { border-color: var(--destructive-text); color: var(--destructive-text); }
.tag--outlined.tag--info      { border-color: var(--info-text); color: var(--info-text); }
.tag--outlined.tag--neutral   { border-color: var(--border); color: var(--foreground); }
.tag--outlined.tag--brand     { border-color: var(--brand-text); color: var(--brand-text); }
.tag--outlined.tag--ai        { border-color: var(--ai-text); color: var(--ai-text); }
.tag--outlined.tag--disabled  { border-color: var(--muted); color: var(--muted-foreground); }

/* ---- Parts ---- */

.tag__dot {
  width: 0.375rem;
  height: 0.375rem;
  border-radius: var(--radius-full);
  background-color: currentColor;
  flex-shrink: 0;
}

.tag__icon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.tag__avatar {
  flex-shrink: 0;
}

.tag__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 1px;
}

